// withdraw_incentives.rue by yakuhito
// Withdraw incentives from a future epoch

import super::super::reward_distributor::*;
import super::super::slot::*;

export fn main(
    REWARD_SLOT_1ST_CURRY_HASH: Bytes32, // after 1st curry
    COMMITMENT_SLOT_1ST_CURRY_HASH: Bytes32, // after 1st curry
    WITHDRAWAL_SHARE_BPS: Int, // / 10000 * committed_value will actually be sent to the recipient
    Truth: RewardDistributorStateTruth,
    reward_slot_counter: Int,
    reward_slot_epoch_time: Int,
    clawback_ph: Bytes32,
    committed_value: Int,
    reward_slot_total_rewards: Int,
    ...reward_slot_next_epoch_initialized: Bool,
) -> (RewardDistributorStateTruth, List<Condition | ReserveCreateCoin>) {    
    let withdrawal_share = committed_value * WITHDRAWAL_SHARE_BPS / 10000;

    let spent_reward_slot_value_hash = slot_value_hash(
        reward_slot_counter,
        reward_slot_epoch_time,
        reward_slot_next_epoch_initialized,
        reward_slot_total_rewards,
    );
    let created_reward_slot_value_hash = slot_value_hash(
        reward_slot_counter + 1,
        reward_slot_epoch_time,
        reward_slot_next_epoch_initialized,
        (reward_slot_total_rewards - withdrawal_share),
    );
    let created_reward_slot_hint = tree_hash_atom(reward_slot_epoch_time as Bytes);

    let spent_commitment_slot_value_hash = slot_value_hash_part(
        reward_slot_epoch_time,
        clawback_ph,
        committed_value,
    );

    (RewardDistributorStateTruth {
        Ephemeral_State: Truth.Ephemeral_State,
        State: RewardDistributorState {
            total_reserves: Truth.State.total_reserves - withdrawal_share,
            active_shares: Truth.State.active_shares,
            reward_info: Truth.State.reward_info,
            round_time_info: Truth.State.round_time_info,
        },
    }, [
        // this also ensures that the wihdrawal doesn't affect the current round
        AssertBeforeSecondsAbsolute {
            seconds: reward_slot_epoch_time,
        },

        // update epoch reward (lower total rewards)
        spend_slot(
            REWARD_SLOT_1ST_CURRY_HASH,
            spent_reward_slot_value_hash,
        ),
        create_slot_with_hint(
            REWARD_SLOT_1ST_CURRY_HASH,
            created_reward_slot_value_hash,
            created_reward_slot_hint,
        ),

        // spend commitment slot, which functions as a ticket
        spend_slot(
            COMMITMENT_SLOT_1ST_CURRY_HASH,
            spent_commitment_slot_value_hash,
        ),

        // make sure the clawback owner wants to go ahead
        ReceiveMessage {
            mode: SENDER_PUZZLE | RECEIVER_PUZZLE,
            message: "w" + tree_hash_pair(
                tree_hash_atom(reward_slot_epoch_time as Bytes),
                tree_hash_atom(committed_value as Bytes),
            ),
            sender: [
                clawback_ph,
            ],
        },

        // condition will be returned by the reserve
        ReserveCreateCoin {
            puzzle_hash: clawback_ph,
            amount: withdrawal_share,
            memos: [clawback_ph],
        },
    ])
}

23522d15e71b71040b05a0ab6be2580ae2b62f72.clvm:
// p2_next_reward_distributor_epoch.clsp by yakuhito
// Coins locked with this puzzle are committed to the next epoch
//    of a reward distributor whose details are curried in.

// To prevent two coins locked in this puzzle (with the same amount) from being
//   spent using one announcement (an attacker would claim half the value - even
//   more if more coins with the same amount exist), this coin's id is used as a
//   unique identifier for the commitment. To do that, instead of using the
//   clawback puzzle hash whose hash is curried in, the actual clawback puzzle
//   will be the provided one wrapped in a nonce layer, with the nonce being this
//   coin's id.

import reward_distributor::slot_value_hash_part;

export fn main(
    SINGLETON_MOD_HASH: Bytes32,
    NONCE_MOD_HASH: Bytes32,
    CLAWBACK_INNER_PUZZLE_HASH: Bytes32, // (sha256tree clawback_puzzle)
    REWARD_DISTRIBUTOR_SINGLETON_STRUCT_HASH: Bytes32, // (sha256tree REWARD_DISTRIBUTOR_SINGLETON_STRUCT)
    REWARD_DISTRIBUTOR_FIRST_EPOCH_START: Int,
    REWARD_DISTRIBUTOR_EPOCH_SECONDS: Int,
    next_epoch_start: Int,
    my_id: Bytes32,
    my_amount: Int,
    ...reward_distributor_inner_puzzle_hash: Bytes32,
) -> (List<Condition>) {
    assert (next_epoch_start - REWARD_DISTRIBUTOR_FIRST_EPOCH_START) % REWARD_DISTRIBUTOR_EPOCH_SECONDS == 0;

    let reward_distributor_puzzle_hash = curry_tree_hash(SINGLETON_MOD_HASH, [
        REWARD_DISTRIBUTOR_SINGLETON_STRUCT_HASH,
        reward_distributor_inner_puzzle_hash
    ]);

    let clawback_puzzle_hash = curry_tree_hash(NONCE_MOD_HASH, [
        tree_hash_atom(my_id),
        CLAWBACK_INNER_PUZZLE_HASH
    ]);

    let commitment_slot_value_hash = slot_value_hash_part(
        next_epoch_start,
        clawback_puzzle_hash,
        my_amount
    );

    [
        // Next epoch cannot possibly have started
        AssertBeforeSecondsAbsolute {
            seconds: next_epoch_start,
        },
        // Next epoch is indeed the next one (previous epoch or older is ongoign)
        AssertSecondsAbsolute {
            seconds: next_epoch_start - REWARD_DISTRIBUTOR_EPOCH_SECONDS,
        },
        // Announcement generated by the reward distributor when there's a commitment
        AssertPuzzleAnnouncement {
            id: sha256(reward_distributor_puzzle_hash + "c" + commitment_slot_value_hash)
        },
        // Impossible to lie about this coin's amount
        AssertMyAmount {
            amount: my_amount,
        },
        // Impossible to lie about this coin's id
        AssertMyCoinId {
            coin_id: my_id,
        }
    ]
}

