5cfbcacf2978de91cc06a181c1beb114cc1b75c3.clvm:
// forge_action_add.rue -- Forge V14 `add` leaf. Testnet research only; unaudited.
//
// V10's MODE_ADD as a merkle leaf. No reserve falls, at least one rises, and the
// LP minted is bracketed by exact_invariant_lp_mint (moved from V10 unchanged,
// imbalance fee included). The LP action coin is the mint eve -- one mojo,
// wrapping the pinned mint inner -- whose id the pool derives and messages.
// Whether the eve actually mints is the TAIL's check against the CAT ring; the
// message it must receive commits to lp_delta, the new supply and the next
// state root.
//
// solution: h, birth, deposits[N], lp_delta, lp_parent_id, settlement_parents[N], settlement_amounts[N]
//
// Each positive deposit is funded by the trader's settlement coin for that asset. V14 names
// it by parent and amount, derives its id, asserts it was spent and holds at least the
// deposit (spec 1.8). A zero deposit needs none, and its two slots are ignored.

import upstream::action::StateTruth;
import forge_curve::*;
import forge_action_common::*;

fn deposit_asserts(
    asset_ids: List<Bytes32>,
    deposits: List<Int>,
    settlement_parents: List<Bytes32>,
    settlement_amounts: List<Int>,
) -> List<Condition> {
    if deposits is nil {
        nil
    } else {
        inline let (asset_id, remaining_assets) = unchecked_cast::<(Bytes32, List<Bytes32>)>(asset_ids);
        inline let (deposit, remaining_deposits) = unchecked_cast::<(Int, List<Int>)>(deposits);
        inline let (settlement_parent, remaining_parents) = unchecked_cast::<(Bytes32, List<Bytes32>)>(settlement_parents);
        inline let (settlement_amount, remaining_amounts) = unchecked_cast::<(Int, List<Int>)>(settlement_amounts);
        // Load-bearing: the mint bracket admits a negative slot beside a large positive one
        // (PR-217 I-1, reproduced at lp_delta 36,611 on [-100000, +500000]).
        assert deposit >= 0;
        if deposit > 0 {
            concat(
                settlement_binding(asset_id, settlement_parent, settlement_amount, deposit),
                deposit_asserts(remaining_assets, remaining_deposits, remaining_parents, remaining_amounts)
            )
        } else {
            deposit_asserts(remaining_assets, remaining_deposits, remaining_parents, remaining_amounts)
        }
    }
}

fn any_positive(list: List<Int>) -> Bool {
    if list is nil {
        false
    } else {
        list.first > 0 || any_positive(list.rest)
    }
}

fn main(
    CONFIG: PoolConfig,
    truth: StateTruth,
    h: Int,
    birth: Int,
    deposits: List<Int>,
    lp_delta: Int,
    lp_parent_id: Bytes32,
    settlement_parents: List<Bytes32>,
    settlement_amounts: List<Int>,
) -> ActionOutput {
    let p = prologue(CONFIG, truth, h, birth);
    // Defence in depth, like the swap leaf's: mutation testing showed
    // `exact_invariant_lp_mint` already refuses every negative and empty case
    // these cover. Kept for the same reason -- see forge_action_swap.rue.
    assert lp_delta > 0;
    assert any_positive(deposits);

    // zip_add fails unless deposits has exactly one entry per reserve.
    let new_reserves = zip_add(p.state.reserves, deposits);
    assert exact_invariant_lp_mint(
        p.state.reserves,
        new_reserves,
        CONFIG.weights,
        p.state.total_lp,
        lp_delta,
        CONFIG.fee_bps,
    );
    let new_total_lp = p.state.total_lp + lp_delta;

    let new_state = ForgeState {
        reserves: new_reserves,
        total_lp: new_total_lp,
        fees_owed: p.state.fees_owed,
        oracle: p.state.oracle,
        prev_root: p.state.prev_root,
        dao_fee_bps: p.state.dao_fee_bps,
        dao_owed: p.state.dao_owed,
        reserve_parents: p.state.reserve_parents,
    };

    ActionOutput {
        state_truth: StateTruth {
            ephemeral_state: p.height,
            actual_state: new_state,
        },
        conditions: concat(
            p.conditions,
            concat(
                deposit_asserts(CONFIG.asset_ids, deposits, settlement_parents, settlement_amounts),
                [
                    // The mint eve is created with amount 1; the TAIL authorizes the
                    // rest of the supply through its extra_delta.
                    lp_handshake(CONFIG, lp_parent_id, LP_MINT_INNER_HASH, 1,
                                 lp_delta, new_total_lp, tree_hash(new_state)),
                ],
            ),
        ),
    }
}

d467b29c7be7892f6923a6e4bc71013b766791dd.clvm:
// forge_action_collect.rue -- Forge V14 `collect` leaf. Testnet research only; unaudited.
//
// Pays the accrued protocol fees out of the named reserves to the curried
// recipient, and zeroes them in state. Permissionless: the recipient is config
// and the amounts are state, so the caller chooses only WHEN, never where or how
// much. Each named index must hold a positive fee -- naming one twice fails on
// the second visit, since the first zeroed it.
//
// the DAO fee owed on the same reserve is paid in the same visit, to the
// curried DAO recipient, and zeroed too. An index qualifies when either fee is
// positive; a zero fee simply pays no coin.
//
// solution: h, indices   (a non-empty list of asset indices)

import upstream::action::StateTruth;
import forge_action_common::*;

struct Collected {
    fees_owed: List<Int>,
    dao_owed: List<Int>,
    ...conditions: List<Condition>,
}

fn payout(index: Int, recipient: Bytes32, amount: Int, rest: List<Condition>) -> List<Condition> {
    if amount > 0 {
        (
            for_reserve(index, CreateCoin {
                puzzle_hash: recipient,
                amount: amount,
                memos: Memos {
                    value: [recipient],
                },
            }),
            rest
        )
    } else {
        rest
    }
}

fn collect(
    fees_owed: List<Int>,
    dao_owed: List<Int>,
    indices: List<Int>,
    protocol_puzzle_hash: Bytes32,
    dao_puzzle_hash: Bytes32,
) -> Collected {
    if indices is nil {
        Collected { fees_owed: fees_owed, dao_owed: dao_owed, conditions: nil }
    } else {
        let index = indices.first;
        let fee = nth_int(fees_owed, index);
        let dao = nth_int(dao_owed, index);
        assert fee > 0 || dao > 0;
        let rest = collect(set_at(fees_owed, index, 0), set_at(dao_owed, index, 0), indices.rest,
                           protocol_puzzle_hash, dao_puzzle_hash);
        Collected {
            fees_owed: rest.fees_owed,
            dao_owed: rest.dao_owed,
            // V13: one recipient, one coin. Two CreateCoins for the same puzzle hash and
            // amount from the same reserve are one coin id twice, and the bundle fails as
            // DUPLICATE_OUTPUT with the fees still owed -- second audit M-1.
            conditions: if protocol_puzzle_hash == dao_puzzle_hash {
                payout(index, protocol_puzzle_hash, fee + dao, rest.conditions)
            } else {
                payout(index, protocol_puzzle_hash, fee,
                       payout(index, dao_puzzle_hash, dao, rest.conditions))
            },
        }
    }
}

fn main(
    CONFIG: PoolConfig,
    truth: StateTruth,
    h: Int,
    birth: Int,
    indices: List<Int>,
) -> ActionOutput {
    let p = prologue(CONFIG, truth, h, birth);
    assert !(indices is nil);
    let collected = collect(p.state.fees_owed, p.state.dao_owed, indices,
                            CONFIG.protocol_puzzle_hash, CONFIG.dao_puzzle_hash);

    ActionOutput {
        state_truth: StateTruth {
            ephemeral_state: p.height,
            actual_state: ForgeState {
                reserves: p.state.reserves,
                total_lp: p.state.total_lp,
                fees_owed: collected.fees_owed,
                oracle: p.state.oracle,
                prev_root: p.state.prev_root,
                dao_fee_bps: p.state.dao_fee_bps,
                dao_owed: collected.dao_owed,
                reserve_parents: p.state.reserve_parents,
            },
        },
        conditions: concat(p.conditions, collected.conditions),
    }
}

0afa5aad4f69d7b92eab93405ac6e1e93efba059.clvm:
// forge_action_dao_fee.rue -- Forge V14 `dao_fee` leaf. Testnet research only; unaudited.
//
// Lowers the pool's DAO fee. The recipient (CONFIG.dao_puzzle_hash) is curried and
// never changes; the rate lives in state so it can move, and this is the only leaf
// that moves it, in one direction: 0 <= new_bps < current. A pool at zero contains
// no transition to a nonzero rate, so irreversibility is topology, not a flag
// (FORGE_DAO_FEE_V11.md, V1 and V4).
//
// Authorization is the pool's own handshake turned around: a coin whose puzzle
// hash IS the DAO recipient sends a mode-23 message -- sender committed by puzzle
// hash, receiver by coin id -- naming the new rate. Consensus commits the receiver
// to THIS pool coin, so the message cannot be replayed against another pool or
// another spend of this one (V2). The DAO proves control of the recipient by
// spending a coin at it; no signature scheme enters the puzzle.
//
// Nothing else moves: reserves, LP, owed fees and the oracle are carried through
// the prologue untouched, so every reserve is re-created at its current amount
// (V3). The prologue still validates the config, pins the height and accumulates
// the oracle, as for any action.
//
// solution: h, new_bps

import upstream::action::StateTruth;
import forge_action_common::*;

fn main(
    CONFIG: PoolConfig,
    truth: StateTruth,
    h: Int,
    birth: Int,
    new_bps: Int,
) -> ActionOutput {
    let p = prologue(CONFIG, truth, h, birth);
    assert new_bps >= 0;
    assert new_bps < p.state.dao_fee_bps;
    assert CONFIG.dao_puzzle_hash != zero_bytes32();

    ActionOutput {
        state_truth: StateTruth {
            ephemeral_state: p.height,
            actual_state: ForgeState {
                reserves: p.state.reserves,
                total_lp: p.state.total_lp,
                fees_owed: p.state.fees_owed,
                oracle: p.state.oracle,
                prev_root: p.state.prev_root,
                dao_fee_bps: new_bps,
                dao_owed: p.state.dao_owed,
                reserve_parents: p.state.reserve_parents,
            },
        },
        conditions: concat(
            p.conditions,
            [
                ReceiveMessage {
                    mode: SENDER_PUZZLE | RECEIVER_COIN,
                    message: dao_fee_message(new_bps),
                    sender: [CONFIG.dao_puzzle_hash],
                },
            ],
        ),
    }
}

169cb2eba9d78d4b36425733e5a83a59709874b2.clvm:
// forge_action_observe.rue -- Forge V14 `observe` leaf. Testnet research only; unaudited.
//
// Snapshots the oracle. The prologue has already accumulated the pre-spend
// price up to `h`; this leaf writes (h . cums) into an observation slot (nonce
// 1, upstream slot.rue, hinted with the slot's own first-curry hash as upstream
// does) and ANNOUNCES it, so any coin in the same bundle can assert the value.
// A same-bundle consumer holding an earlier observation computes
// TWAP = (cum - cum_past) / (h - h_past).
//
// An announcement rather than a message, settled 09-05: a message must name its
// receiver and fails the spend if nothing receives it, so an observe with no
// consumer present could never land. The announcement is one-directional.
//
// solution: h
//
// State is unchanged beyond the prologue. Reading back a past slot in the same
// action is not implemented in this revision; the slot is created for a future
// consumer to spend by message.

import upstream::action::StateTruth;
import forge_action_common::*;

fn main(
    CONFIG: PoolConfig,
    SLOT_1ST_CURRY_HASH: Bytes32,
    truth: StateTruth,
    h: Int,
    birth: Int,
) -> ActionOutput {
    let p = prologue(CONFIG, truth, h, birth);
    let value_hash = tree_hash((p.height, p.state.oracle.cums));

    ActionOutput {
        state_truth: StateTruth {
            ephemeral_state: p.height,
            actual_state: p.state,
        },
        conditions: concat(
            p.conditions,
            [
                CreateCoin {
                    puzzle_hash: curry_tree_hash(SLOT_1ST_CURRY_HASH, [tree_hash_atom(value_hash)]),
                    amount: 0,
                    memos: Memos {
                        value: [SLOT_1ST_CURRY_HASH],
                    },
                },
                CreatePuzzleAnnouncement {
                    message: tree_hash(["forge-observe-v1", p.height, p.state.oracle.cums]),
                },
            ],
        ),
    }
}

9ee0128e996916dde16cb9ca9887c3f64bba82c9.clvm:
// forge_action_remove.rue -- Forge V14 `remove` leaf. Testnet research only; unaudited.
//
// V10's MODE_REMOVE as a merkle leaf. Burning `burn` LP releases an exactly
// proportional share of every reserve, floored per asset, checked by
// exact_withdrawal (moved from V10 unchanged). A single-asset vault charges its
// liquidity fee on the crossing, via vault_fee_bps; every multi-asset pool pays
// out free. `burn < total_lp`, so the pool always outlives the withdrawal.
//
// The LP action coin is the melt coin -- exactly `burn` LP wrapping the pinned
// melt inner, whose only behavior is to destroy its whole amount -- and the
// TAIL additionally requires it to have a CAT parent, so a coin fabricated out
// of ordinary mojos cannot stand in for a burn.
//
// solution: h, burn, lp_parent_id, payouts[N]
//
// Payouts go to the offer settlement puzzle of each asset; the finalizer tags
// them to the right reserve, and the CAT layer wraps them for CAT reserves.

import upstream::action::StateTruth;
import forge_curve::*;
import forge_action_common::*;

fn payout_conditions(index: Int, payouts: List<Int>) -> List<Condition> {
    if payouts is nil {
        nil
    } else {
        let payout = payouts.first;
        if payout > 0 {
            (
                for_reserve(index, CreateCoin { puzzle_hash: OFFER_MOD_HASH, amount: payout }),
                payout_conditions(index + 1, payouts.rest)
            )
        } else {
            assert payout == 0;
            payout_conditions(index + 1, payouts.rest)
        }
    }
}

fn main(
    CONFIG: PoolConfig,
    truth: StateTruth,
    h: Int,
    birth: Int,
    burn: Int,
    lp_parent_id: Bytes32,
    payouts: List<Int>,
) -> ActionOutput {
    let p = prologue(CONFIG, truth, h, birth);
    assert burn > 0;
    // V12: everything above the locked minimum is redeemable; the pool outlives every
    // withdrawal because LOCKED_BURN always remains -- CHIP-0062 review P1.
    assert burn <= p.state.total_lp - LOCKED_BURN;

    // zip_sub fails unless payouts has exactly one entry per reserve.
    let new_reserves = zip_sub(p.state.reserves, payouts);
    assert exact_withdrawal(
        p.state.reserves,
        new_reserves,
        burn,
        p.state.total_lp,
        vault_fee_bps(p.state.reserves, CONFIG.fee_bps),
    );
    let new_total_lp = p.state.total_lp - burn;

    let new_state = ForgeState {
        reserves: new_reserves,
        total_lp: new_total_lp,
        fees_owed: p.state.fees_owed,
        oracle: p.state.oracle,
        prev_root: p.state.prev_root,
        dao_fee_bps: p.state.dao_fee_bps,
        dao_owed: p.state.dao_owed,
        reserve_parents: p.state.reserve_parents,
    };

    ActionOutput {
        state_truth: StateTruth {
            ephemeral_state: p.height,
            actual_state: new_state,
        },
        conditions: concat(
            p.conditions,
            concat(
                payout_conditions(0, payouts),
                [
                    lp_handshake(CONFIG, lp_parent_id, LP_MELT_INNER_HASH, burn,
                                 0 - burn, new_total_lp, tree_hash(new_state)),
                ],
            ),
        ),
    }
}

01e8bdc7a184d454f13ebb32b73c4e3f7e6c1bfb.clvm:
// forge_action_swap.rue -- Forge V14 `swap` leaf. Testnet research only; unaudited.
//
// V10's MODE_SWAP as a merkle leaf. Exactly one reserve rises and one falls; the
// claimed output is bracketed by exact_swap_output (moved from V10 unchanged);
// the protocol fee is a slice of the output, ACCRUED into fees_owed rather than
// paid as a second coin -- `collect` pays it out in batches. The trader receives
// the curve output minus the fee at the offer settlement puzzle, exactly as V10.
//
// solution: h, birth, asset_in, asset_out, gross_input, claimed_output,
//           settlement_parent, settlement_amount
//
// V14: the trader's settlement is named by its PARENT and AMOUNT, and the leaf derives its
// id. It asserts the coin was spent (ASSERT_CONCURRENT_SPEND) and holds at least
// gross_input -- the router's fee is carved out of the same coin, so it may hold more.
// V13 took the coin id and bound the asset only; the amount was enforced by the CAT ring
// and conservation alone (spec 1.8).
//
// Every other reserve is untouched by construction: only two indices are
// rewritten, and the finalizer re-creates every reserve from the new state.

import upstream::action::StateTruth;
import forge_curve::*;
import forge_action_common::*;

fn main(
    CONFIG: PoolConfig,
    truth: StateTruth,
    h: Int,
    birth: Int,
    asset_in: Int,
    asset_out: Int,
    gross_input: Int,
    claimed_output: Int,
    settlement_parent: Bytes32,
    settlement_amount: Int,
) -> ActionOutput {
    let p = prologue(CONFIG, truth, h, birth);
    let n = count_ints(p.state.reserves);
    // The five checks below are DEFENCE IN DEPTH, not the defence. Mutation
    // testing on 2026-09-10 (scripts/mutate-v12.py) deleted each in turn and the
    // suite still passed for four of them: `exact_swap_output` is unsatisfiable
    // for a negative or zero amount, and an out-of-range index fails the reserve
    // lookup before any assert is reached. Only `asset_in != asset_out` is
    // independently pinned.
    //
    // They are kept because TibetSwap V2 was drained in August 2026 by exactly
    // the gap they close -- a swap that enforced one reserve up and one down but
    // never that the input be positive. If the curve's bracket were ever widened,
    // these become the defence, and nothing would notice them going. Do not
    // remove them on the grounds that a test still passes without them.
    assert asset_in != asset_out;
    assert asset_in >= 0 && asset_in < n;
    assert asset_out >= 0 && asset_out < n;
    assert gross_input > 0;
    assert claimed_output > 0;

    let reserve_in = nth_int(p.state.reserves, asset_in);
    let reserve_out = nth_int(p.state.reserves, asset_out);
    assert exact_swap_output(
        reserve_in,
        reserve_out,
        reserve_in + gross_input,
        reserve_out - claimed_output,
        nth_int(CONFIG.weights, asset_in),
        nth_int(CONFIG.weights, asset_out),
        CONFIG.fee_bps,
    );
    let protocol_fee = protocol_fee_owed(claimed_output, CONFIG.protocol_fee_bps);
    // the DAO fee is a second slice of the same output, at the CURRENT rate in
    // state, owed inside the same reserve until `collect` pays it to the DAO.
    let dao_fee = protocol_fee_owed(claimed_output, p.state.dao_fee_bps);

    let new_state = ForgeState {
        reserves: add_at(add_at(p.state.reserves, asset_in, gross_input), asset_out, 0 - claimed_output),
        total_lp: p.state.total_lp,
        // The fee stays physically inside the out reserve, owed.
        fees_owed: add_at(p.state.fees_owed, asset_out, protocol_fee),
        oracle: p.state.oracle,
        prev_root: p.state.prev_root,
        dao_fee_bps: p.state.dao_fee_bps,
        dao_owed: add_at(p.state.dao_owed, asset_out, dao_fee),
        reserve_parents: p.state.reserve_parents,
    };

    ActionOutput {
        state_truth: StateTruth {
            ephemeral_state: p.height,
            actual_state: new_state,
        },
        conditions: concat(
            p.conditions,
            concat(
                settlement_binding(nth_bytes(CONFIG.asset_ids, asset_in), settlement_parent, settlement_amount, gross_input),
                [
                    for_reserve(asset_out, CreateCoin {
                        puzzle_hash: OFFER_MOD_HASH,
                        amount: claimed_output - protocol_fee - dao_fee,
                    }),
                ],
            ),
        ),
    }
}

eb8d6f4cecc121bd3133238ac4d492564fd634b0.clvm:
// forge_lp_cat_tail.rue -- Forge V14 pool-scoped LP CAT TAIL. Testnet research only; unaudited.
//
// V10's TAIL with one change: the pool's authorization arrives as a CHIP-0025
// message instead of a coin announcement. The pool SENDS with mode 23 -- sender
// committed by puzzle hash, receiver by coin id -- to the LP action coin whose id
// it derived (V10's lock, part 1). This TAIL RECEIVES against the pool's full
// singleton puzzle hash, rebuilt from its curried launcher id and the pool's
// inner puzzle hash supplied in the solution, the way forge_reserve_FORGE did.
// Consensus commits the receiving coin, so `AssertMyCoinId` and the action coin
// id in the message are gone; one condition replaces three.
//
// Everything else is V10, including the two locks this puzzle owns:
//   * `parent_is_cat || expected_delta > 0`: a melt destroys supply, so it can
//     only come from a coin that held supply -- security finding 4. CHIP-0040's
//     standard TAIL lacks this line, which is why it was declined when the
//     pool-scoped TAIL was first built.
//     Be precise about what it buys (mutation run, 2026-09-11): with this line
//     deleted, a melt coin fabricated from ordinary mojos IS accepted -- but
//     only with extra_delta = -2*burn to satisfy the delta lock below, and CAT2's
//     ring then charges for that delta, so a real sibling must shrink by `burn`
//     and supply genuinely falls. The pool is not drained; the attacker wastes
//     mojos. This line therefore does not stand alone: it removes the dependence
//     on the ring's sign convention and makes the messaged coin have to be real
//     LP. Pinned as policy by _test_v12_lp_receive_forgery.py case C; the
//     finding-4 probe in _test_v12_actions.py is refused by the delta lock first.
//   * `effective_delta == expected_delta`: the ring's real supply change is the
//     one the pool authorized, and the message also commits to the new supply
//     and the next state root.
//
// GENESIS. At creation the pool has not spent yet, so no singleton of its
// launcher can send a message; V10 let a creator-controlled coin vouch for the
// first mint. V12 uses the one coin whose id this TAIL already knows: the
// launcher. singleton_launcher announces sha256tree((full_puzzle_hash 1
// key_value_list)) exactly once, when it creates the eve. V12 fixes that list to
// (expected_delta, this eve's own coin id), read from the CAT truths rather than the
// solution -- so a genesis mint is possible only in the launcher's own bundle, only
// once, and only by the ONE eve the launcher named. V11 fixed the list to
// (expected_delta) alone, and any coin could assert it: two funded eves each minted
// the whole supply, which is CHIP-0062 review finding P0. The registry's `register`
// asserts the same announcement with the list fixed to (total_lp, eve_coin_id), so a
// registered pool's genesis supply, its eve and its state all agree.
// A pool nobody registers is creator-trusted at genesis, as V10 was -- and
// undiscoverable.
//
// Curried: (launcher_id, protocol_version). The tree hash is the LP asset id,
// unique per pool and per revision.

import forge_action_common::*;

// V13 (the second-audit revision) is protocol 14: a fresh LP asset id per pool and per
// revision, so LP of any earlier revision can never be authorized by a pool of this one,
// and protocol-13 LP cannot cross into a protocol-14 pool.
inline const PROTOCOL_VERSION: Int = 15;

struct LpAction {
    expected_delta: Int,
    new_total_lp: Int,
    next_state_root: Bytes32,
    pool_inner_puzzle_hash: Bytes32,
    // zero for every mint and melt the pool authorizes by message; the pool's
    // full puzzle hash for the genesis mint the launcher authorizes
    genesis_pool_puzzle_hash: Bytes32,
}

fn main(
    launcher_id: Bytes32,
    protocol_version: Int,
    truths_any: Any,
    parent_is_cat_any: Any,
    _lineage_proof: Any,
    delta_any: Any,
    _inner_conditions: Any,
    action: LpAction,
) -> List<Condition> {
    assert launcher_id != zero_bytes32();
    assert protocol_version == PROTOCOL_VERSION;
    assert action.expected_delta != 0;
    assert action.new_total_lp >= 0;

    let parent_is_cat = unchecked_cast::<Bool>(parent_is_cat_any);
    let delta = unchecked_cast::<Int>(delta_any);
    let action_coin_amount = cat_my_amount(truths_any);
    assert action_coin_amount > 0;

    assert parent_is_cat || action.expected_delta > 0;

    let effective_delta = if parent_is_cat { delta } else { action_coin_amount + delta };
    assert effective_delta == action.expected_delta;

    if action.genesis_pool_puzzle_hash == zero_bytes32() {
        // The pool authorizes this supply change by message.
        assert action.pool_inner_puzzle_hash != zero_bytes32();
        let pool_full_puzzle_hash = curry_tree_hash(
            SINGLETON_MOD_HASH,
            [
                tree_hash((SINGLETON_MOD_HASH, (launcher_id, SINGLETON_LAUNCHER_PUZZLE_HASH))),
                action.pool_inner_puzzle_hash,
            ],
        );
        [
            ReceiveMessage {
                mode: SENDER_PUZZLE | RECEIVER_COIN,
                message: lp_message(action.expected_delta, action.new_total_lp, action.next_state_root),
                sender: [pool_full_puzzle_hash],
            },
        ]
    } else {
        // Genesis: a mint from nothing (no CAT parent) of exactly the supply the
        // launcher named when it created the eve at this puzzle hash.
        assert !parent_is_cat;
        assert action.expected_delta > 0;
        assert action.new_total_lp == action.expected_delta;
        [
            AssertCoinAnnouncement {
                // V12: the announced list names THIS eve's coin id, so exactly one coin can
                // assert the launcher's one announcement -- CHIP-0062 review P0, "genesis can
                // authorize more LP than pool state records".
                id: sha256(launcher_id + tree_hash([action.genesis_pool_puzzle_hash, 1,
                                                    [action.expected_delta, cat_my_coin_id(truths_any)]])),
            },
        ]
    }
}

fn cat_my_coin_id(truths: Any) -> Bytes32 {
    let outer = unchecked_cast::<(Any, Any)>(truths);
    let id_and_coin = unchecked_cast::<(Any, Any)>(outer.rest);
    unchecked_cast::<Bytes32>(id_and_coin.first)
}

// CAT2 truths:
// ((inner_puzzle_hash . cat_struct) .
//  (my_coin_id . (parent_coin_info, full_puzzle_hash, my_amount)))
fn cat_my_amount(truths: Any) -> Int {
    let outer = unchecked_cast::<(Any, Any)>(truths);
    let id_and_coin = unchecked_cast::<(Any, Any)>(outer.rest);
    let coin_info = unchecked_cast::<(Any, Any)>(id_and_coin.rest);
    let puzzle_hash_and_amount = unchecked_cast::<(Any, Any)>(coin_info.rest);
    let amount_and_nil = unchecked_cast::<(Any, Any)>(puzzle_hash_and_amount.rest);
    unchecked_cast::<Int>(amount_and_nil.first)
}

