// forge_registry_init.rue -- the registry's one-shot `init` leaf. Testnet research only; unaudited.
//
// Creates the two sentinel slots that bracket every key -- 0x00..00 and
// 0xff..ff, each pointing at the other -- and flips `initialized`. It can run
// once: a second pair of sentinels would let the same key be inserted twice,
// once between each pair, which is exactly what the sorted list exists to
// prevent. The registry is minted with state (0 . 0); its first spend is this.
//
// solution: nil

import upstream::action::StateTruth;
import upstream::slot_helpers::*;
import forge_action_common::*;
import forge_registry_common::*;

fn main(
    CONSTANTS: RegistryConstants,
    truth: StateTruth,
) -> RegistryOutput {
    let state = unchecked_cast::<RegistryState>(truth.actual_state);
    assert state.initialized == 0;
    assert state.pool_count == 0;

    RegistryOutput {
        state_truth: StateTruth {
            ephemeral_state: truth.ephemeral_state,
            // V15: the launch fee seeds the state; set_fee moves it from here on.
            actual_state: RegistryState { initialized: 1, pool_count: 0, creation_fee: CONSTANTS.creation_fee },
        },
        conditions: [
            create_slot_with_hint(
                CONSTANTS.slot_1st_curry_hash,
                slot_value_hash(min_key(), zero_bytes32(), min_key(), max_key()),
                CONSTANTS.hint,
            ),
            create_slot_with_hint(
                CONSTANTS.slot_1st_curry_hash,
                slot_value_hash(max_key(), zero_bytes32(), min_key(), max_key()),
                CONSTANTS.hint,
            ),
        ],
    }
}

208a2a0099d88b77b5ff12b29327357ff013f2fc.clvm:
// forge_registry_register.rue -- the registry's `register` leaf. Testnet research only; unaudited.
//
// Runs in the same bundle as a pool's creation. It:
//
//   1. derives the pool's launcher id from the launcher's parent, so the coin
//      it names necessarily runs the standard launcher puzzle;
//   2. rebuilds the pool's full puzzle hash from that launcher id and the
//      claimed config and genesis (forge_registry_common), and asserts the
//      launcher's announcement that it created a coin at exactly that hash --
//      so what is registered is what was minted, at V12, and nothing else;
//   3. asserts the creation fee was paid to the treasury by an offer settlement
//      whose nonce is this launcher id, so one payment registers one pool;
//   3b. V13: asserts the genesis LP settlement paid LOCKED_BURN of this pool's LP
//      to the zero puzzle hash under the same nonce. The floor is therefore burned
//      before the pool is listed -- not held by the creator as a transferable coin
//      that can never be redeemed, which is what the reference website lane did in
//      V12 (second audit, "LOCKED_BURN burn unimplemented"). Only the TAIL's
//      genesis branch can create that asset, so this also proves the mint happened
//      rather than merely that it was authorized (second audit, INFO).
//   3c. V14: derives each reserve's parent from the grandparent named in the solution
//      and the reserve launcher's puzzle hash, and asserts that launcher's announcement
//      that it created the reserve -- so a registered pool has FUNDED reserves, at the
//      parents its state records, by construction (fourth review, R-1). The parents are
//      derived, never claimed: `reserve_parents` left the solution.
//   4. inserts the pool's key between two adjacent slots, spending both by
//      message and re-creating them around the new key. Adjacency is
//      structural: the left slot's right pointer and the right slot's left
//      pointer are the same variables as the neighbours' own keys, so a pair of
//      slots that are not neighbours cannot both be spent.
//
// Uniqueness is the sorted list's: `left_key < key < right_key` between
// adjacent slots admits a key exactly once. Duplicate economic configs are
// therefore refused, whatever their launcher.
//
// The launcher's key-value list is fixed to (total_lp): that is the list the
// LP TAIL's genesis branch requires, so registering a pool proves its genesis
// LP supply is exactly the total_lp in its eve state.
//
// solution: launcher_parent_id, config, reserves, total_lp, dao_fee_bps,
//           reserve_grandparents, eve_coin_id,
//           (left_launcher_id, left_left_key), (right_launcher_id, right_right_key),
//           left_key, right_key

import upstream::action::StateTruth;
import upstream::slot_helpers::*;
import forge_action_common::*;
import forge_registry_common::*;

struct Neighbour {
    launcher_id: Bytes32,
    ...far_key: Bytes32,
}

fn main(
    CONSTANTS: RegistryConstants,
    truth: StateTruth,
    launcher_parent_id: Bytes32,
    config: PoolConfig,
    reserves: List<Int>,
    total_lp: Int,
    dao_fee_bps: Int,
    reserve_grandparents: List<Bytes32>,
    eve_coin_id: Bytes32,
    left: Neighbour,
    right: Neighbour,
    left_key: Bytes32,
    right_key: Bytes32,
) -> RegistryOutput {
    let state = unchecked_cast::<RegistryState>(truth.actual_state);
    assert state.initialized == 1;

    // The launcher coin: parent, the standard launcher puzzle, one mojo. Derived with
    // `coinid`, like the reserve parents below: a parent that is not 32 bytes is refused
    // by the operator, in this leaf, rather than deriving a launcher no coin can be and
    // failing on its announcement. The zero check stays: `coinid` checks width, not
    // existence, and offline it is the only refusal of a fabricated zero-parent launcher (T-5).
    assert launcher_parent_id != zero_bytes32();
    let launcher_id = coinid(launcher_parent_id, SINGLETON_LAUNCHER_PUZZLE_HASH, 1);

    assert valid_pool(CONSTANTS, launcher_id, config, reserves, total_lp, dao_fee_bps);
    // V14: the reserve parents, derived from the grandparents and the launcher's hash.
    let reserve_parents = derived_reserve_parents(CONSTANTS, config.asset_ids, reserves, reserve_grandparents);
    let reserve_inners = reserve_inner_hashes(CONSTANTS, singleton_struct_hash(launcher_id), config.asset_ids, 0);
    let pool_puzzle_hash = pool_full_puzzle_hash(CONSTANTS, launcher_id, config, reserves, total_lp, dao_fee_bps, reserve_parents);

    let key = pool_key(config);
    assert left_key < key;
    assert key < right_key;

    // V15: the fee charged is the one in STATE (set by the treasury through set_fee), not
    // the launch constant. A fee of zero means a free registration: no settlement coin is
    // asserted, so none need exist.
    let fee_conditions: List<Condition> = if state.creation_fee == 0 {
        nil
    } else {
        [
            // settlement_payments announces sha256tree(nonce . payments)
            AssertPuzzleAnnouncement {
                id: sha256(OFFER_MOD_HASH + tree_hash((
                    launcher_id,
                    [[CONSTANTS.treasury_puzzle_hash, state.creation_fee, [CONSTANTS.treasury_puzzle_hash]]],
                ))),
            },
        ]
    };

    RegistryOutput {
        state_truth: StateTruth {
            ephemeral_state: truth.ephemeral_state,
            actual_state: RegistryState { initialized: 1, pool_count: state.pool_count + 1, creation_fee: state.creation_fee },
        },
        conditions: concat(
            // V14: every reserve was created, at its amount, by a launcher at the derived parent.
            reserve_launch_asserts(reserve_parents, reserve_inners, reserves, launcher_id),
            concat(
            [
                // V13: the burned floor. settlement_payments announces sha256tree(nonce . payments)
                // per notarized group; the CAT layer passes the announcement through under the
                // settlement's full CAT puzzle hash.
                AssertPuzzleAnnouncement {
                    id: sha256(cat_puzzle_hash(config.lp_tail_hash, OFFER_MOD_HASH)
                               + tree_hash((launcher_id, [[zero_bytes32(), LOCKED_BURN]]))),
                },
                // singleton_launcher announces (sha256tree (list full_puzzle_hash amount key_value_list));
                // V12: the list is (total_lp, eve_coin_id) -- what the TAIL's genesis mint requires,
                // so exactly one eve can claim the genesis supply (finding P0)
                AssertCoinAnnouncement {
                    id: sha256(launcher_id + tree_hash([pool_puzzle_hash, 1, [total_lp, eve_coin_id]])),
                },
                // the two neighbours, spent by message
                spend_slot(CONSTANTS.slot_1st_curry_hash,
                           slot_value_hash(left_key, left.launcher_id, left.far_key, right_key)),
                spend_slot(CONSTANTS.slot_1st_curry_hash,
                           slot_value_hash(right_key, right.launcher_id, left_key, right.far_key)),
                // the new slot and the neighbours re-created around it
                create_slot_with_hint(CONSTANTS.slot_1st_curry_hash,
                                      slot_value_hash(key, launcher_id, left_key, right_key), CONSTANTS.hint),
                create_slot_with_hint(CONSTANTS.slot_1st_curry_hash,
                                      slot_value_hash(left_key, left.launcher_id, left.far_key, key), CONSTANTS.hint),
                create_slot_with_hint(CONSTANTS.slot_1st_curry_hash,
                                      slot_value_hash(right_key, right.launcher_id, key, right.far_key), CONSTANTS.hint),
                // For anything in the bundle that wants to know a pool was listed. V12
                // carries the whole identity rather than just the key and the launcher:
                // every value here was already proved above -- `pool_puzzle_hash` was
                // rebuilt from the config and matched against the launcher's own
                // announcement, and `total_lp` and `eve_coin_id` came out of that same
                // announcement -- so a consumer that asserts this one announcement learns
                // where the pool coin lives, what its genesis supply is and which eve
                // holds it, without having to re-derive any of it or trust an index.
                // Nothing in the registry reads this; it exists to be verified against.
                CreatePuzzleAnnouncement {
                    message: tree_hash(["forge-registered-v15", key, launcher_id,
                                        pool_puzzle_hash, total_lp, eve_coin_id]),
                },
            ],
            fee_conditions,
            ),
        ),
    }
}

08853b1daf3a11208c6cee3ab7b9cdf47e72046e.clvm:
// forge_registry_set_fee.rue -- Forge V15 registry `set_fee` leaf. Testnet research only; unaudited.
//
// Sets the creation fee future pairs pay. V14 curried the fee into the registry, so
// changing it meant rolling the registry over (a new registry, old pairs listed under
// the retired one). V15 holds the fee in RegistryState (owner, 2026-10-07): `init`
// seeds it from CONSTANTS.creation_fee, `register` charges whatever the state holds,
// and this is the only leaf that moves it, in either direction, zero included (zero
// makes registration free: `register` then asserts no settlement at all).
//
// Authorization is the DAO-fee handshake turned to the treasury: a coin whose puzzle
// hash IS the treasury (CONSTANTS.treasury_puzzle_hash, the recipient of every creation
// fee) sends a mode-23 message -- sender committed by puzzle hash, receiver by coin id --
// naming the new fee. Consensus commits the receiver to THIS registry coin, so the
// message cannot be replayed against another spend of it, and the treasury proves
// control of its recipient by spending a coin at it; no signature scheme enters the
// puzzle. The treasury on mainnet is a lock, which emits the message from its own
// action.
//
// Nothing else moves: the slot list is untouched (no slot is spent or created), the
// pool count is carried, and `initialized` must already be 1 so the fee cannot be set
// on a registry that was never opened.
//
// solution: new_fee
import upstream::action::StateTruth;
import forge_action_common::*;
import forge_registry_common::*;

fn main(
    CONSTANTS: RegistryConstants,
    truth: StateTruth,
    new_fee: Int,
) -> RegistryOutput {
    let state = unchecked_cast::<RegistryState>(truth.actual_state);
    assert state.initialized == 1;
    assert new_fee >= 0;
    // Audit F7: the fee goes into the hashed state, so it is stored after arithmetic and
    // is canonical whatever bytes the solution spelled it with. The treasury's message
    // names the same canonical value.
    let fee = new_fee + 0;

    RegistryOutput {
        state_truth: StateTruth {
            ephemeral_state: truth.ephemeral_state,
            actual_state: RegistryState { initialized: 1, pool_count: state.pool_count, creation_fee: fee },
        },
        conditions: [
            ReceiveMessage {
                mode: SENDER_PUZZLE | RECEIVER_COIN,
                message: registry_fee_message(fee),
                sender: [CONSTANTS.treasury_puzzle_hash],
            },
        ],
    }
}

